import numpy as np
import xarray as xr
import xskillscore as xs

def nmse_impl(a, b, dim=None, weights=None, skipna=False, keep_attrs=False, axis=None):
    import xskillscore.core.np_deterministic as xs_internal
    import warnings

    if not isinstance(a, xr.DataArray) and not isinstance(b, xr.DataArray):
        if (dim is not None) and (axis is not None):
            warnings.warn("The `dim` keyword is unused with non xarray.DataArray inputs")
        if axis is None:
            axis = 0
            a = np.ravel(a)
            b = np.ravel(b)
            if weights is not None:
                weights = np.ravel(weights)
        try:
            return 1 - xs_internal._r2(a, b, weights, axis, skipna)
        except ValueError:
            print('Data along `axis` must have the same dimension as `weights`')
    else:
        if (dim is not None) and (axis is not None):
            warnings.warn("The `axis` keyword is unused with xarray.DataArray inputs")
        try:
            return 1 - xs.r2(a, b, dim, weights, skipna, keep_attrs)
        except ValueError:
            print('Data along `dim` must have the same dimension as `weights`')

def test_nmse():
    a = np.array([1.0, 2.0, 3.0])
    b = np.array([1.1, 1.9, 3.1])

    # SS_res = (1-1.1)^2 + (2-1.9)^2 + (3-3.1)^2 = 0.01 + 0.01 + 0.01 = 0.03
    # mean(a) = 2.0
    # SS_tot = (1-2)^2 + (2-2)^2 + (3-2)^2 = 1 + 0 + 1 = 2.0
    # NMSE = 0.03 / 2.0 = 0.015

    res = nmse_impl(a, b)
    print(f"NMSE (numpy): {res}")
    assert np.isclose(res, 0.015)

    da_a = xr.DataArray(a, dims=['time'])
    da_b = xr.DataArray(b, dims=['time'])
    res_da = nmse_impl(da_a, da_b, dim='time')
    print(f"NMSE (xarray): {res_da.values}")
    assert np.isclose(res_da.values, 0.015)

if __name__ == "__main__":
    test_nmse()
    print("Tests passed!")

